import { ActiveEffects } from "../components/ActiveEffects.js";
import { Status } from "../components/Status.js";
import { Position } from "../components/Position.js";
import { canonicalStatusKey } from "./effectSemantics.js";
import { statusStrength } from "./statusFacade.js";

export const SHADOW_CLOAK_REARM_KEY = "shadow_cloak_rearm";
export const SHADOW_CLOAK_REARM_TURNS = 7;

function normalizeStatusType(value) {
  return String(value || "").trim().toLowerCase();
}

/**
 * Remove projected/explicit status entries by semantic status type.
 * This updates both ActiveEffects (canonical) and Status fallback.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} entityId
 * @param {string} statusType
 * @returns {boolean} true if any entry was removed
 */
export function clearStatusType(world, entityId, statusType) {
  const id = Number(entityId || 0) | 0;
  const wanted = normalizeStatusType(statusType);
  if (!(id > 0) || !wanted) return false;

  let changed = false;

  const ae = world.get(id, ActiveEffects);
  if (ae && Array.isArray(ae.effects)) {
    for (let i = ae.effects.length - 1; i >= 0; i--) {
      const effect = ae.effects[i];
      const key = String(effect?.key || "").trim().toLowerCase();
      if (!key) continue;
      if (canonicalStatusKey(key) !== wanted) continue;
      ae.effects.splice(i, 1);
      changed = true;
    }
  }

  const status = world.get(id, Status);
  if (status && Array.isArray(status.statuses)) {
    for (let i = status.statuses.length - 1; i >= 0; i--) {
      const type = normalizeStatusType(status.statuses[i]?.type);
      if (type !== wanted) continue;
      status.statuses.splice(i, 1);
      changed = true;
    }
  }

  return changed;
}

/**
 * Canonical stealth-offense pathway.
 * While hidden, offensive actions consume the one-shot ambush buff
 * (`shadow_cloak`) but keep invisibility active.
 * Emits `stealth:offense` for witness-based AI reactions.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 * @param {number} entityId
 * @param {{ reason?: string, mode?: string, targetId?: number }} [context]
 * @returns {{ hidden:boolean, ambushConsumed:boolean }}
 */
export function breakStealthOnOffense(world, entityId, context = {}) {
  const id = Number(entityId || 0) | 0;
  if (!(id > 0)) return { hidden: false, ambushConsumed: false };
  const hidden = statusStrength(world, id, "invisible") > 0;
  if (!hidden) return { hidden: false, ambushConsumed: false };
  const ambushConsumed = clearStatusType(world, id, "shadow_cloak");
  if (ambushConsumed) {
    const ae = world.get(id, ActiveEffects);
    if (ae && Array.isArray(ae.effects)) {
      let tracker = null;
      for (let i = 0; i < ae.effects.length; i++) {
        const e = ae.effects[i];
        if (String(e?.key || "").trim().toLowerCase() !== SHADOW_CLOAK_REARM_KEY) continue;
        tracker = e;
        break;
      }
      if (!tracker) {
        ae.effects.push({
          key: SHADOW_CLOAK_REARM_KEY,
          turnsLeft: SHADOW_CLOAK_REARM_TURNS,
          potency: 1,
          stacks: 1,
          sourceId: id,
        });
      } else {
        tracker.turnsLeft = SHADOW_CLOAK_REARM_TURNS;
        tracker.potency = 1;
        tracker.stacks = 1;
      }
    }
  }
  const pos = world.get(id, Position);

  world.emit?.("stealth:offense", {
    entityId: id,
    reason: String(context.reason || "offense"),
    mode: String(context.mode || "melee"),
    targetId: Number(context.targetId || 0) | 0,
    at: pos ? { x: pos.x | 0, y: pos.y | 0 } : null,
    hidden: true,
    ambushConsumed,
  });
  return { hidden: true, ambushConsumed };
}
import { ActiveEffects } from "../components/ActiveEffects.js";
import { Position } from "../components/Position.js";
import { Faction } from "../components/Faction.js";
import { forEachInRadius } from "../utils/spatialIndex.js";
import { areFactionsHostile } from "../utils/factionHostility.js";
import { upsertTimedEffect } from "../utils/effectSemantics.js";
import {
  SHADOW_CLOAK_REARM_KEY,
  SHADOW_CLOAK_REARM_TURNS,
} from "../utils/stealthAmbush.js";

const REARM_SAFE_RADIUS = 9;

function activeEffect(ae, key) {
  if (!ae || !Array.isArray(ae.effects)) return null;
  const wanted = String(key || "").trim().toLowerCase();
  for (let i = 0; i < ae.effects.length; i++) {
    const e = ae.effects[i];
    if (!e) continue;
    const k = String(e.key || "").trim().toLowerCase();
    if (k !== wanted) continue;
    if ((Number(e.turnsLeft || 0) | 0) <= 0) continue;
    if ((Number(e.onsetLeft || 0) | 0) > 0) continue;
    return e;
  }
  return null;
}

function effectIndex(ae, key) {
  if (!ae || !Array.isArray(ae.effects)) return -1;
  const wanted = String(key || "").trim().toLowerCase();
  for (let i = 0; i < ae.effects.length; i++) {
    const e = ae.effects[i];
    if (!e) continue;
    if (String(e.key || "").trim().toLowerCase() === wanted) return i;
  }
  return -1;
}

/**
 * Rearms shadow-cloak opener after a quiet period while invisibility remains active.
 * This lets stealth gameplay continue without forcing visibility toggles.
 *
 * @param {import("../../lib/ecs-js/index.js").World} world
 */
export function stealthAmbushSystem(world) {
  for (const [id, ae, pos] of world.query(ActiveEffects, Position)) {
    if (!ae || !Array.isArray(ae.effects) || !pos) continue;

    const invisible = activeEffect(ae, "invisible");
    const shadowCloak = activeEffect(ae, "shadow_cloak");
    const trackerIdx = effectIndex(ae, SHADOW_CLOAK_REARM_KEY);
    const tracker = trackerIdx >= 0 ? ae.effects[trackerIdx] : null;

    if (!invisible) {
      if (trackerIdx >= 0) ae.effects.splice(trackerIdx, 1);
      continue;
    }

    if (shadowCloak) {
      if (trackerIdx >= 0) ae.effects.splice(trackerIdx, 1);
      continue;
    }

    if (!tracker) continue;

    const selfFaction = String(world.get(id, Faction)?.key || "");
    let hostileNearby = false;
    forEachInRadius(world, pos.x | 0, pos.y | 0, REARM_SAFE_RADIUS, (otherId) => {
      if (hostileNearby || otherId === id) return;
      const otherFaction = String(world.get(otherId, Faction)?.key || "");
      if (!selfFaction || !otherFaction) return;
      if (areFactionsHostile(selfFaction, otherFaction)) hostileNearby = true;
    });

    if (hostileNearby) {
      tracker.turnsLeft = SHADOW_CLOAK_REARM_TURNS;
      continue;
    }

    if ((Number(tracker.turnsLeft || 0) | 0) > 1) continue;

    upsertTimedEffect(ae.effects, {
      key: "shadow_cloak",
      turnsLeft: Math.max(1, Number(invisible.turnsLeft || 1) | 0),
      potency: 1,
      stacks: 1,
      sourceId: id,
    });
    const removeIdx = effectIndex(ae, SHADOW_CLOAK_REARM_KEY);
    if (removeIdx >= 0) ae.effects.splice(removeIdx, 1);
    world.emit?.("stealth:rearmed", {
      entityId: id,
      at: { x: pos.x | 0, y: pos.y | 0 },
    });
  }
}

