const results = await Promise.all([
  tools.exec_command({cmd:"deno eval \"import { SPELL_DEFS } from './src/rules/data/spells.js'; for (const [id,s] of Object.entries(SPELL_DEFS)) { const effects=(s.effects||[]).filter(e=>e.kind==='status'||e.kind==='effect'); if(effects.length>0) console.log(id+'\\t'+effects.map(e=>e.kind+':'+(e.status||e.effect)).join(' + ')); }\"","workdir":"/home/pjensen/Repos/JSHack","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"rg -n -C 2 \"statusStrength\\([^\\n]+\\\"(stunned|stun|rooted|frozen|stasis|silenced|silence|mindwipe|mindlocked|invisible|blinded|confused|slowed|webbed|sleep|asleep)\\\"\" src/rules --glob '*.js'","workdir":"/home/pjensen/Repos/JSHack","yield_time_ms":10000,"max_output_tokens":18000}),
  tools.exec_command({cmd:"rg -n \"statusStrength\\(|effectStrength\\(\" src/rules --glob '*.js' | cut -d: -f1 | sort | uniq -c | sort -nr","workdir":"/home/pjensen/Repos/JSHack","yield_time_ms":10000,"max_output_tokens":5000}),
  tools.exec_command({cmd:"rg -n -C 5 \"spellId ===|script ===|case ['\\\"]|registerSpell|SPELL_SCRIPT|spellScripts|REGISTRY\" src/rules/scripts/spells.js | head -n 260","workdir":"/home/pjensen/Repos/JSHack","yield_time_ms":10000,"max_output_tokens":16000})
]); for (const r of results) text(r.output);

