// rules/systems/intentValidationSystem.js
// Pre-validation pass that strips intents from actors who cannot act.
// Runs first in the 'intents' phase so downstream systems can assume valid actors.
//
// Currently strips intents for:
//   - Dead actors (hp <= 0)
//   - Sleeping actors
//   - Stunned actors (have "stunned" status), except WaitIntent

import { Vitality } from "../components/Vitality.js";
import { MoveIntent } from "../components/Intents/MoveIntent.js";
import { FlyIntent } from "../components/Intents/FlyIntent.js";
import { AttackIntent } from "../components/Intents/AttackIntent.js";
import { AttackDirectionIntent } from "../components/Intents/AttackDirectionIntent.js";
import { WaitIntent } from "../components/Intents/WaitIntent.js";
import { DrinkIntent } from "../components/Intents/DrinkIntent.js";
import { UseIntent } from "../components/Intents/UseIntent.js";
import { ThrowIntent } from "../components/Intents/ThrowIntent.js";
import { ApplyIntent } from "../components/Intents/ApplyIntent.js";
import { EquipIntent } from "../components/Intents/EquipIntent.js";
import { DropIntent } from "../components/Intents/DropIntent.js";
import { PickupIntent } from "../components/Intents/PickupIntent.js";
import { CastSpellIntent } from "../components/Intents/CastSpellIntent.js";
import { RangedAttackIntent } from "../components/Intents/RangedAttackIntent.js";
import { EngraveIntent } from "../components/Intents/EngraveIntent.js";
import { PrayIntent } from "../components/Intents/PrayIntent.js";
import { DisarmIntent } from "../components/Intents/DisarmIntent.js";
import { InteractIntent } from "../components/Intents/InteractIntent.js";
import { SearchIntent } from "../components/Intents/SearchIntent.js";
import { SetPostureIntent } from "../components/Intents/SetPostureIntent.js";
import { Channeling } from "../components/Channeling.js";
import { effectStrength, statusStrength } from "../utils/statusFacade.js";
import { sleepPreventsAction } from "../utils/sleep.js";

/** All intent components that should be stripped when an actor cannot act. */
const ALL_INTENTS = [
  MoveIntent, FlyIntent, AttackIntent, AttackDirectionIntent, WaitIntent, DrinkIntent, UseIntent,
  ThrowIntent, ApplyIntent, EquipIntent, DropIntent, PickupIntent,
  CastSpellIntent, RangedAttackIntent, EngraveIntent, PrayIntent,
  DisarmIntent, InteractIntent, SearchIntent,
  SetPostureIntent,
];

/** Intents stripped while stunned (WaitIntent is allowed to burn the turn). */
const STUNNED_BLOCKED = ALL_INTENTS.filter(c => c !== WaitIntent);

/** Intents stripped during stasis; MoveIntent is retained as an explicit cancellation. */
const STASIS_BLOCKED = ALL_INTENTS.filter(c => c !== WaitIntent && c !== MoveIntent);

/** Intents stripped while rooted (can act but cannot move). */
const ROOTED_BLOCKED = [MoveIntent, FlyIntent];

/** Intents stripped during channeling (everything except WaitIntent). */
const CHANNELING_BLOCKED = ALL_INTENTS.filter(c => c !== WaitIntent);

/**
 * Remove a list of intent components from an entity.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} id
 * @param {readonly any[]} intents
 * @returns {boolean}
 */
function stripIntents(world, id, intents) {
  let removed = false;
  for (let i = 0; i < intents.length; i++) {
    if (world.has(id, intents[i])) {
      try { world.remove(id, intents[i]); } catch {}
      removed = true;
    }
  }
  return removed;
}

/**
 * Remove all intent components from an entity.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} id
 * @returns {boolean}
 */
function stripAllIntents(world, id) {
  return stripIntents(world, id, ALL_INTENTS);
}

/**
 * Mark a queued movement as cancelled while leaving it available for the
 * movement consumer to observe and consume.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} id
 * @param {string} reason
 * @returns {boolean}
 */
function cancelMoveIntent(world, id, reason) {
  const intent = world.get(id, MoveIntent);
  if (!intent) return false;
  if (intent.cancelled === true && intent.cancelReason === reason) return false;
  world.set(id, MoveIntent, {
    ...intent,
    cancelled: true,
    cancelReason: String(reason || "unknown"),
  });
  return true;
}

/**
 * Intent validation system — runs first in the intents phase.
 * Strips invalid intents from actors who are dead or stunned so downstream
 * systems never process actions for incapacitated entities. Stunned actors
 * may only keep WaitIntent, which lets the player explicitly burn the turn.
 *
 * @param {import('../../lib/ecs-js/index.js').World} world
 */
export function intentValidationSystem(world) {
  for (const [id, vit] of world.query(Vitality)) {
    // Dead actors cannot act
    if (vit.hp <= 0) {
      stripAllIntents(world, id);
      continue;
    }

    // Sleeping actors cannot act until a wake event clears the sleep status.
    if (sleepPreventsAction(world, id)) {
      const blocked = stripAllIntents(world, id);
      if (blocked) {
        try {
          world.emit?.("intent:blocked", { actor: id, reason: "asleep" });
        } catch (e) {
          console.debug("[intentValidationSystem] emit intent:blocked failed:", e);
        }
      }
      continue;
    }

    // Stunned actors may only wait
    const stunned = statusStrength(world, id, "stunned") + effectStrength(world, id, "gaze_beam") > 0;
    const inStasis = statusStrength(world, id, "stasis") > 0;
    if (stunned) {
      const blocked = stripIntents(world, id, STUNNED_BLOCKED);
      if (blocked) {
        try {
          world.emit?.("intent:blocked", { actor: id, reason: "stunned" });
        } catch (e) {
          console.debug("[intentValidationSystem] emit intent:blocked failed:", e);
        }
      }
      continue;
    }

    // Stasis may only wait. Keep MoveIntent as an explicit cancellation so
    // downstream consumers can observe why the attempted move was rejected.
    if (inStasis) {
      const cancelled = cancelMoveIntent(world, id, "stasis");
      const blocked = stripIntents(world, id, STASIS_BLOCKED) || cancelled;
      if (blocked) {
        try {
          world.emit?.("intent:blocked", { actor: id, reason: "stasis" });
        } catch (e) {
          console.debug("[intentValidationSystem] emit intent:blocked failed:", e);
        }
      }
      continue;
    }

    // Rooted actors can act but cannot move
    const rooted = statusStrength(world, id, "rooted") + effectStrength(world, id, "frost_nova") > 0;
    if (rooted) {
      const blocked = stripIntents(world, id, ROOTED_BLOCKED);
      if (blocked) {
        try {
          world.emit?.("intent:blocked", { actor: id, reason: "rooted" });
        } catch (e) {
          console.debug("[intentValidationSystem] emit intent:blocked failed:", e);
        }
      }
    }

    // Channeling actors can only wait — strip everything else
    if (world.has(id, Channeling)) {
      for (let i = 0; i < CHANNELING_BLOCKED.length; i++) {
        if (world.has(id, CHANNELING_BLOCKED[i])) {
          try { world.remove(id, CHANNELING_BLOCKED[i]); } catch {}
        }
      }
    }
  }
}
export function movementSystem(world) {
  const tiles = getTileQuerySnapshot(world);
  // Start from snapshot and reserve destinations as actors move this tick.
  const blocking = new Set(tiles.blockedByCell);

  for (const [actor, intent] of world.query(MoveIntent)) {
    try {
      const pos = world.get(actor, Position);
      if (!pos) { world.remove(actor, MoveIntent); continue; }
      if (intent.cancelled === true) { world.remove(actor, MoveIntent); continue; }

      // Dead entities must not move — prevents a spurious "moved" event firing
      // after the entity dies mid-tick (e.g. grid bug killed while it still has
      // an AI-queued MoveIntent).  The event would be harmless for most listeners
      // but the deferred position update produced by world.set would be applied
      // at end-of-tick, briefly placing the entity at the wrong tile before it
      // is destroyed by cleanupSystem — enough to confuse any system that reads
      // the entity's position between the flush and the cleanup.
      const vit = world.get(actor, Vitality);
      if (vit && (vit.hp | 0) <= 0) { world.remove(actor, MoveIntent); continue; }
      if (sleepPreventsMovement(world, actor)) { world.remove(actor, MoveIntent); continue; }
      if (statusStrength(world, actor, "stasis") > 0) {
        world.set(actor, MoveIntent, {
          ...intent,
          cancelled: true,
          cancelReason: "stasis",
        });
        world.emit?.("intent:blocked", { actor, reason: "stasis" });
        world.remove(actor, MoveIntent);
        continue;
      }
      if (statusStrength(world, actor, "stunned") + effectStrength(world, actor, "gaze_beam") > 0
        || statusStrength(world, actor, "rooted") + effectStrength(world, actor, "frost_nova") > 0) {
        world.remove(actor, MoveIntent);
        continue;
      }

      const intendedDx = intent.dx | 0;
      const intendedDy = intent.dy | 0;
      let mdx = intendedDx;
      let mdy = intendedDy;

      // Confusion: movement inputs become a deterministic random misstep.
      const confusePower = statusStrength(world, actor, "confused");
      if (confusePower > 0 && (intendedDx !== 0 || intendedDy !== 0)) {
        const options = MISSTEP_DIRS.filter(d => !(d.dx === intendedDx && d.dy === intendedDy));
        if (options.length > 0) {
          const posSalt = (((pos.x | 0) & 0xffff) << 16) ^ ((pos.y | 0) & 0xffff);
          const r = mulberry32(combatSeed(world.seed, world.step, actor, posSalt, 0xC0F00D11));
          const idx = (r() * options.length) | 0;
          ({ dx: mdx, dy: mdy } = options[idx]);
          world.emit("status:confused-misstep", {
            actor,
            from: { dx: intendedDx, dy: intendedDy },
            to: { dx: mdx, dy: mdy },
          });
        }
      }

      // Overloaded actors cannot move diagonally; force to dominant axis.
      if (mdx !== 0 && mdy !== 0) {
        const enc = /** @type {any} */ (world.get(actor, Encumbrance));
        if (enc?.overloaded) {
          if (Math.abs(intendedDx) >= Math.abs(intendedDy)) { mdy = 0; } else { mdx = 0; }
        }
      }

      // "Slowed" skips every Nth movement attempt (stacks+1 cadence).
      // 1 stack → move every 2nd attempt, 2 → every 3rd, 3 → every 4th.
      const slowedStacks = Math.min(3, statusStrength(world, actor, "slowed")
        + effectStrength(world, actor, "bog_curse")
        + effectStrength(world, actor, "iron_flesh"));
      if (slowedStacks > 0) {
        const tick = (slowMoveTicks.get(actor) || 0) + 1;
        slowMoveTicks.set(actor, tick);
        if (tick % (slowedStacks + 1) !== 0) {
          world.emit("movement:slowed", { actor, stacks: slowedStacks, x: pos.x, y: pos.y, dx: mdx, dy: mdy });
          continue;
        }
      } else {
        slowMoveTicks.delete(actor);
      }

      const nx = pos.x + mdx;
      const ny = pos.y + mdy;
      const k = xyKey(nx, ny);
      const target = tiles.livingByCell.get(k) || 0;

      // Record facing direction on every move attempt (successful or not)
      const facingBefore = world.has(actor, Facing)
        ? normalizeFacingVector(world.get(actor, Facing)?.dx, world.get(actor, Facing)?.dy)
        : null;
      if (world.has(actor, Facing)) {
        world.set(actor, Facing, { dx: mdx, dy: mdy });
      }
      const facingAfter = normalizeFacingVector(mdx, mdy);
      const facingChangedFromKnownDirection = !!(
        facingBefore
        && facingAfter
        && (facingBefore.dx !== facingAfter.dx || facingBefore.dy !== facingAfter.dy)
      );
      if (isFacingTurnCostEnabled(world) && facingChangedFromKnownDirection) {
        continue;
      }

      // Flying entities bypass terrain (water, lava, trees, mountains) but not walls/void.
      const actorFlying = world.has(actor, Flying);
      const terrainBlocked = actorFlying ? !isFlyable(nx, ny) : !isWalkable(nx, ny);

      const canTraverseWebs = hasIdentity(world, actor, "spider")
        || statusStrength(world, actor, "web_immune") > 0;
      const spiderCanTraverseWeb =
        canTraverseWebs
        && isWalkable(nx, ny)
        && blocking.has(k)
        && tiles.blockedByCell.has(k)
        && isBlockedOnlyByWebs(world, tiles, nx, ny);

      // Centipede heads can step into tiles occupied by their own body segments.
      // The body cascade listener will shift the segment out after the move.
      let centipedeCanPassOwnBody = false;
      if (blocking.has(k) && !spiderCanTraverseWeb) {
