Deno.test("divine_shield applies one authored breakable ward", () => {
  const world = makeWorld();
  const caster = makeCaster(world, 5, 5);

  runSpellScript(world, caster, SPELL_DEFS.divine_shield, {});

  const keys = effectKeys(world, caster);
